import type { CssConfigReturn, TokenVariableNames } from "pandwind/types/typings";

type RecordValue = Record<string, unknown>;

export const GENERATED_CSS_TYPES_HEADER =
	"// Generated by pandwind-codemod css generate; do not edit.";

const isRecord = (value: unknown): value is RecordValue =>
	typeof value === "object" && value !== null && !Array.isArray(value);

const asRecord = (value: unknown): RecordValue => (isRecord(value) ? value : {});

const sortedKeys = (value: unknown): string[] => Object.keys(asRecord(value)).toSorted();

const quote = (value: string): string => JSON.stringify(value);

const generatedTypePrintWidth = 100;

const typeKey = (value: string): string =>
	/^[A-Za-z_$][A-Za-z0-9_$]*$/u.test(value) ? value : quote(value);

const formatUnion = (
	values: readonly string[],
	prefixLength: number,
	continuationIndent: string,
): string => {
	if (values.length === 0) return "never";
	const inline = values.join(" | ");
	if (prefixLength + inline.length <= generatedTypePrintWidth) return inline;
	return `\n${continuationIndent}| ${values.join(`\n${continuationIndent}| `)}`;
};

const numericLiteral = (value: string): string | undefined => {
	if (!/^-?(?:0|[1-9]\d*)(?:\.\d+)?$/u.test(value)) return undefined;
	const number = Number(value);
	return Number.isFinite(number) && String(number) === value ? String(number) : undefined;
};

const authoredKey = (value: string): string[] => {
	const numeric = numericLiteral(value);
	return numeric === undefined ? [quote(value)] : [quote(value), numeric];
};

const colorPropertyNames = new Set([
	"color",
	"background",
	"backgroundColor",
	"borderColor",
	"borderTopColor",
	"borderRightColor",
	"borderBottomColor",
	"borderLeftColor",
	"outlineColor",
	"textDecorationColor",
	"textEmphasisColor",
	"fill",
	"stroke",
]);

const tokenNames = (tokens: RecordValue, group: string): string[] =>
	sortedKeys(tokens[group]).flatMap(authoredKey);

const paletteRoles = (source: unknown, prefix = ""): string[] => {
	if (typeof source === "string")
		return [prefix === "" ? "colorPalette" : `colorPalette.${prefix}`];
	if (!isRecord(source)) return [];
	return Object.entries(source).flatMap(([name, value]) =>
		paletteRoles(value, prefix === "" ? name : `${prefix}.${name}`),
	);
};

const paletteNames = (preset: CssConfigReturn): string[] => sortedKeys(preset.colorPalettes);

const paletteSourceValues = (tokens: RecordValue, source: unknown): string[] => {
	if (typeof source !== "string") return paletteRoles(source);
	if (!source.startsWith("colors.")) return [];
	const prefix = source.slice("colors.".length);
	return sortedKeys(tokens.colors).flatMap((tokenName) => {
		if (tokenName === prefix) return ["colorPalette"];
		if (tokenName.startsWith(`${prefix}.`))
			return [`colorPalette.${tokenName.slice(prefix.length + 1)}`];
		return [];
	});
};

const paletteValueNames = (preset: CssConfigReturn): string[] => {
	const tokens = asRecord(preset.tokens);
	return Object.values(asRecord(preset.colorPalettes))
		.flatMap((source) => paletteSourceValues(tokens, source))
		.toSorted();
};

const propertyTokenNames = (tokens: RecordValue, property: unknown): string[] => {
	if (property === true || !isRecord(property)) return [];
	const explicitTokenNames = Object.keys(property)
		.filter((key) => key !== "$strict" && key !== "$tokens")
		.flatMap(authoredKey)
		.toSorted();
	const referencedTokenNames =
		typeof property.$tokens === "string" ? tokenNames(tokens, property.$tokens) : [];
	return [...new Set([...explicitTokenNames, ...referencedTokenNames])];
};

const hasOpenValues = (preset: CssConfigReturn, property: unknown): boolean =>
	preset.strict !== true || property === true || (isRecord(property) && property.$strict === false);

const propertyValue = (
	preset: CssConfigReturn,
	tokens: RecordValue,
	propertyName: string,
	property: unknown,
	paletteValues: readonly string[],
): string => {
	const values = propertyTokenNames(tokens, property);
	if (colorPropertyNames.has(propertyName)) values.push(...paletteValues.map(quote));
	if (hasOpenValues(preset, property)) values.push("GeneratedOpenCssValue");
	values.push("FirstThatWorksValue", "null");
	const value = formatUnion(
		[...new Set(values)],
		`\treadonly ${typeKey(propertyName)}?: `.length,
		"\t\t",
	);
	return value.startsWith("\n", 0) ? value : ` ${value}`;
};

const propertyNames = (preset: CssConfigReturn): string[] =>
	sortedKeys(preset.properties).filter((name) => name !== "$all" && name !== "colorPalette");

const conditionNames = (preset: CssConfigReturn): string[] => sortedKeys(preset.conditions);

const generatedPropertyBlock = (preset: CssConfigReturn): string => {
	const tokens = asRecord(preset.tokens);
	const paletteValues = paletteValueNames(preset);
	const entries = propertyNames(preset).map((propertyName) => {
		const property = asRecord(preset.properties)[propertyName];
		return `\treadonly ${typeKey(propertyName)}?:${propertyValue(
			preset,
			tokens,
			propertyName,
			property,
			paletteValues,
		)};`;
	});
	const palettes = paletteNames(preset);
	if (palettes.length > 0) {
		entries.push("\treadonly colorPalette?: GeneratedColorPaletteReference;");
	} else {
		entries.push("\treadonly colorPalette?: never;");
	}
	for (const condition of conditionNames(preset))
		entries.push(`\treadonly ${typeKey(condition)}?: GeneratedStyle;`);
	entries.push("\treadonly [selector: GeneratedSelector]: GeneratedStyle | undefined;");
	return entries.join("\n");
};

const generatedDynamicPropertyBlock = (preset: CssConfigReturn): string => {
	const entries = propertyNames(preset).map(
		(propertyName) => `\treadonly ${typeKey(propertyName)}?: GeneratedDynamicValue;`,
	);
	if (paletteNames(preset).length > 0) {
		entries.push("\treadonly colorPalette?: GeneratedColorPaletteReference;");
	} else {
		entries.push("\treadonly colorPalette?: never;");
	}
	for (const condition of conditionNames(preset))
		entries.push(`\treadonly ${typeKey(condition)}?: GeneratedDynamicStyle;`);
	entries.push("\treadonly [selector: GeneratedSelector]: GeneratedDynamicStyle | undefined;");
	entries.push("\treadonly [property: string]: GeneratedDynamicValue;");
	return entries.join("\n");
};

const generatedTypeDeclarations = (preset: CssConfigReturn): string => {
	const properties = asRecord(preset.properties);
	const propertyNamesList = propertyNames(preset);
	const declarations: string[] = [];
	if (propertyNamesList.some((propertyName) => hasOpenValues(preset, properties[propertyName]))) {
		declarations.push(
			"type GeneratedOpenString = string & {};",
			"type GeneratedOpenCssValue = GeneratedOpenString | number;",
		);
	}
	if (properties.$all === true) {
		declarations.push(
			"type GeneratedOpenValue =",
			"\t| string",
			"\t| number",
			"\t| null",
			"\t| undefined",
			"\t| GeneratedOpenStyle",
			"\t| readonly GeneratedOpenValue[];",
			"type GeneratedOpenStyle = { readonly [property: string]: GeneratedOpenValue };",
		);
	}
	return declarations.join("\n");
};

const generatedStyleType = (preset: CssConfigReturn): string => {
	const openProperties = asRecord(preset.properties).$all === true;
	const openStyle = openProperties ? " & GeneratedOpenStyle" : "";
	return `export type GeneratedStyle = {
${generatedPropertyBlock(preset)}
}${openStyle};

export type GeneratedDynamicStyle = {
${generatedDynamicPropertyBlock(preset)}
};`;
};

export interface GenerateCssTypesOptions {
	readonly presetImport: string;
	readonly presetExport?: string;
	/** Select the token custom-property spelling used by the generated runtime. */
	readonly tokenVariableNames?: TokenVariableNames;
}

export interface GeneratedCssTypesSource {
	readonly source: string;
	readonly propertyCount: number;
	readonly conditionCount: number;
	readonly tokenCount: number;
}

const importLine = (options: GenerateCssTypesOptions): string => {
	const presetExport = options.presetExport ?? "preset";
	if (presetExport === "default") return `import preset from ${quote(options.presetImport)};`;
	return `import { ${presetExport} as preset } from ${quote(options.presetImport)};`;
};

/** Render a concrete, preset-bound CSS facade without evaluating mapped types. */
export const generateCssTypes = (
	preset: CssConfigReturn,
	options: GenerateCssTypesOptions,
): GeneratedCssTypesSource => {
	const tokens = asRecord(preset.tokens);
	const tokenCount = Object.values(tokens).reduce(
		(count: number, group) => count + sortedKeys(group).length,
		0,
	);
	const paletteReference =
		paletteNames(preset).length > 0
			? formatUnion(
					[
						...paletteNames(preset).map(quote),
						"{ readonly [condition: string]: GeneratedColorPaletteReference }",
					],
					"type GeneratedColorPaletteReference = ".length,
					"\t",
				)
			: "never";
	const runtimeOptions =
		options.tokenVariableNames === undefined
			? ""
			: `, { tokenVariableNames: ${quote(options.tokenVariableNames)} }`;
	const source = `${GENERATED_CSS_TYPES_HEADER}
// Regenerate after changing the preset or upgrading Pandwind.
import { createGeneratedCss } from "pandwind/css/generated";
import type { CssFn, FirstThatWorksValue } from "pandwind/css";
${importLine(options)}

type GeneratedSelector = \`&\${string}\` | \`\${string}&\` | \`@\${string}\`;
type GeneratedDynamicValue =
\t| string
\t| number
\t| boolean
\t| null
\t| undefined
\t| GeneratedColorPaletteReference
\t| GeneratedDynamicStyle
\t| readonly GeneratedDynamicValue[];
type GeneratedColorPaletteReference =${paletteReference.startsWith("\n", 0) ? paletteReference : ` ${paletteReference}`};
${generatedTypeDeclarations(preset)}
${generatedStyleType(preset)}

export type GeneratedCss = CssFn<GeneratedStyle, GeneratedDynamicStyle>;

export const css: GeneratedCss = /* @__PURE__ */ createGeneratedCss<GeneratedStyle, GeneratedDynamicStyle>(preset${runtimeOptions});
`;
	return {
		source,
		propertyCount: propertyNames(preset).length,
		conditionCount: conditionNames(preset).length,
		tokenCount,
	};
};
